import{_ as p,C as i,o as e,c as l,a2 as a,b as d,w as o,a as s,E as n,a3 as A}from"./chunks/framework.DZUUNQ77.js";const m=JSON.parse('{"title":"这是什么","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-virtualxposed.md","filePath":"guide/what-is-virtualxposed.md","lastUpdated":1784053534000}'),E={name:"guide/what-is-virtualxposed.md"};function h(u,t,c,g,B,_){const r=i("Mermaid");return e(),l("div",null,[t[1]||(t[1]=a('<h1 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h1><p><strong>VirtualXposed</strong> 是一个 Android 应用，它让你<strong>在免 Root、不解锁 Bootloader、不刷机</strong>的前提下，运行 Xposed 模块来 Hook（改写）其它应用的方法调用。</p><p>它支持 Android 5.0 ~ 10.0，当前仓库版本为 <code>0.22.0</code>。</p><h2 id="一句话定位" tabindex="-1">一句话定位 <a class="header-anchor" href="#一句话定位" aria-label="Permalink to &quot;一句话定位&quot;">​</a></h2><blockquote><p>把 Xposed 框架的能力，从“需要 Root + 刷入系统”降级到“装一个普通 App 就能用”。</p></blockquote><p>传统 Xposed 的工作方式是：你解锁 Bootloader → 刷入带 Xposed 框架的系统镜像 → 重启 → 模块在 Zygote 进程里全局生效，影响所有 App。</p><p>VirtualXposed 换了一条路：它自己就是一个普通 App，内部用一套<strong>应用虚拟化引擎</strong>把目标 App 装进自己的进程里跑，再在虚拟进程里用 <strong>ART 方法 Hook</strong> 加载 Xposed 模块。模块只对“装进 VirtualXposed 里运行的那个 App”生效，对系统里直接安装的 App 无影响。</p>',7)),(e(),d(A,null,{default:o(()=>[n(r,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20TRAD%5B%22%E4%BC%A0%E7%BB%9F%20Xposed%22%5D%0A%20%20%20%20T1%5B%22%E8%A7%A3%E9%94%81%20BL%20%2F%20%E5%88%B7%E6%9C%BA%20%2F%20Root%22%5D%20--%3E%20T2%5B%22Xposed%20%E6%B3%A8%E5%85%A5%20Zygote%22%5D%0A%20%20%20%20T2%20--%3E%20T3%5B%22%E5%85%A8%E5%B1%80%E6%89%80%E6%9C%89%20App%20%E7%94%9F%E6%95%88%22%5D%0A%20%20end%0A%20%20subgraph%20VXP%5B%22VirtualXposed%22%5D%0A%20%20%20%20V1%5B%22%E8%A3%85%E4%B8%80%E4%B8%AA%E6%99%AE%E9%80%9A%20App%22%5D%20--%3E%20V2%5B%22VirtualApp%20%E6%8A%8A%E7%9B%AE%E6%A0%87%20App%20%E6%8B%89%E8%BF%9B%E6%9C%AC%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20%20%20V2%20--%3E%20V3%5B%22epic%20%E5%9C%A8%E6%9C%AC%E8%BF%9B%E7%A8%8B%E5%81%9A%20ART%20Hook%22%5D%0A%20%20%20%20V3%20--%3E%20V4%5B%22%E5%8F%AA%E5%AF%B9%E8%99%9A%E6%8B%9F%E7%8E%AF%E5%A2%83%E9%87%8C%E7%9A%84%20App%20%E7%94%9F%E6%95%88%22%5D%0A%20%20end%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<p>两条路殊途：传统 Xposed 改系统以换取全局生效，VirtualXposed 不碰系统、只换进程内生效。</p><h2 id="它由两个核心拼成" tabindex="-1">它由两个核心拼成 <a class="header-anchor" href="#它由两个核心拼成" aria-label="Permalink to &quot;它由两个核心拼成&quot;">​</a></h2><p>VirtualXposed 不是一个从零写的框架，它站在两个项目的肩膀上：</p><table tabindex="0"><thead><tr><th>项目</th><th>作用</th><th>仓库</th></tr></thead><tbody><tr><td><strong>VirtualApp</strong></td><td>应用虚拟化引擎：在 App 进程内用 Java 重新实现 AMS/PMS 等系统服务，让任意 App 能“安装”进沙箱运行</td><td><a href="https://github.com/asLody/VirtualApp" target="_blank" rel="noreferrer">asLody/VirtualApp</a></td></tr><tr><td><strong>epic</strong></td><td>非 Root 下的 ART 方法 Hook 引擎，基于 inline hook 改写 ART 方法入口</td><td><a href="https://github.com/tiann/epic" target="_blank" rel="noreferrer">tiann/epic</a></td></tr></tbody></table><p>VirtualXposed 的贡献在于把两者缝合：让 epic 跑在 VirtualApp 虚拟出来的进程里，并把 Xposed 的标准 API（<code>XposedBridge</code>、<code>XC_LoadPackage</code> 等）暴露出来，这样<strong>现成的 Xposed 模块可以零改动接入</strong>。</p><h2 id="它能做什么" tabindex="-1">它能做什么 <a class="header-anchor" href="#它能做什么" aria-label="Permalink to &quot;它能做什么&quot;">​</a></h2><p>站在使用者视角，VirtualXposed 能让你在不 Root 的手机上：</p><ul><li>安装一个目标 App（比如微信、QQ、Instagram）到 VirtualXposed 内部</li><li>安装一个 Xposed 模块到 VirtualXposed 内部</li><li>在 Xposed Installer 里勾选启用模块</li><li>重启 VirtualXposed（不是重启手机），模块即生效</li></ul><p>典型用途：防撤回、去广告、应用变量（机型伪装）、虚拟定位、微信/QQ 增强等。仓库的 <a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/main/CHINESE.md" target="_blank" rel="noreferrer">CHINESE.md</a> 列了一份实测可用的模块清单。</p><h2 id="它不能做什么" tabindex="-1">它不能做什么 <a class="header-anchor" href="#它不能做什么" aria-label="Permalink to &quot;它不能做什么&quot;">​</a></h2><p>有两道硬限制，根因都在“它本质上还是个普通 App”：</p><ol><li><strong>不能修改系统本身</strong>。它运行在用户态 App 进程里，没有系统权限，所以重力工具箱这类要改系统设置/系统 UI 的模块无效。</li><li><strong>不支持资源 Hook</strong>。资源 Hook 需要在资源加载阶段介入，当前实现只在 ART 方法层面 Hook，资源钩子不会起作用。用资源 Hook 的主题美化模块（如 MDWechat）相应功能不生效。</li></ol><p>详细边界见<a href="./limitations">能力边界与限制</a>。</p><h2 id="这个文档站讲什么" tabindex="-1">这个文档站讲什么 <a class="header-anchor" href="#这个文档站讲什么" aria-label="Permalink to &quot;这个文档站讲什么&quot;">​</a></h2><p>本站不是使用手册（使用说明在 README/CHINESE.md 已经写清楚了），而是一份<strong>逐层拆解实现原理的教学文档</strong>。读完它，你会清楚：</p><ul><li>VirtualApp 是怎么在 App 进程里“假装自己是系统”的</li><li>系统 Service 为什么能被替换、被拦截</li><li>一个虚拟 App 的 Activity 是怎么骗过真实 AMS 启动起来的</li><li>数据隔离（每个虚拟 App 独立数据目录）是怎么做到的</li><li>epic 怎么在不 Root 的情况下 Hook ART 方法</li><li>Xposed 模块是怎么被加载进虚拟进程并生效的</li></ul><p>如果你只是想用它，看<a href="./quick-start">快速使用</a>就够了；想搞懂它怎么做到的，从<a href="./../architecture/overview">架构总览</a>开始往下读。</p>',17))])}const b=p(E,[["render",h]]);export{m as __pageData,b as default};
